import type { Client as OpenApiClient } from "openapi-fetch";

import { apiErrorFrom } from "./errors.ts";
import type { paths } from "./v1.gen.ts";

/**
 * The SDK's RESOURCE METHODS — `client.limits.list()`,
 * `client.runs.create(slug, { inputs })` — one per /v1 operation, named
 * as the CLI names it (`limits list`), generated into ./resources.gen.ts
 * from the same operation table as the CLI's commands and the MCP
 * server's tools (scripts/generate.mjs; gitignored, regenerated by every
 * build). Path parameters are arguments, in path order; query and body
 * fields are one input object, typed from ./v1.gen.ts; the answer is the
 * response's data, and a non-2xx throws ApiError. Decided 2026-10-11,
 * before 1.0: nobody guesses `api.POST("/scripts/{slug}/runs", { params:
 * { path: { slug } }, body })` wrapped in `unwrap(...)`. The names are
 * the CLI's, so the surface snapshot (surfaces.test.ts) covers them.
 */

export type RawClient = OpenApiClient<paths>;

type Method = "get" | "post" | "put" | "patch" | "delete";
type Op<P extends keyof paths, M extends Method> = M extends keyof paths[P]
  ? paths[P][M]
  : never;
type NonEmpty<T, Else> = [NonNullable<T>] extends [never]
  ? Else
  : NonNullable<T>;

type QueryOf<O> = O extends { parameters: { query?: infer Q } }
  ? NonEmpty<Q, unknown>
  : unknown;
type BodyOf<O> = O extends { requestBody?: infer R }
  ? NonEmpty<R, never> extends { content: { "application/json": infer B } }
    ? B
    : unknown
  : unknown;

/** An operation's query and body fields, as one object. */
export type Input<P extends keyof paths, M extends Method> = QueryOf<Op<P, M>> &
  BodyOf<Op<P, M>>;

type Json<R> = R extends { content: { "application/json": infer J } }
  ? J
  : undefined;
/** What an operation answers on success (its 2xx JSON). */
export type Output<P extends keyof paths, M extends Method> =
  Op<P, M> extends { responses: infer R }
    ? {
        [K in keyof R]: K extends 200 | 201 | 202
          ? Json<R[K]>
          : K extends 204
            ? undefined
            : never;
      }[keyof R]
    : never;

export type RequestOptions = {
  /**
   * Sent as Idempotency-Key. Every write gets one anyway (one per call,
   * reused on the client's own retries); pass yours to make a retry
   * YOU make — a rerun job, a redelivered webhook — count once too.
   */
  idempotencyKey?: string;
  /** More request headers. */
  headers?: Record<string, string>;
};

/** One operation's request, as the generated method describes it. */
export type Call = {
  method: Method;
  path: string;
  /** The input's fields that go in the query string; the rest is the body. */
  query: readonly string[];
  hasBody: boolean;
  /** Takes raw bytes as the body (the route's media type). */
  rawBody?: string;
  /** Answers with raw bytes: the method returns a Blob. */
  rawResponse?: string;
};

/** Raw bytes for an operation that takes them, such as a file upload. */
export type Content = Blob | ArrayBuffer | Uint8Array | string;

/** Makes the call; the data, or throws ApiError. */
export async function call<T>(
  client: RawClient,
  op: Call,
  pathParams: Record<string, string | number>,
  input: object | undefined,
  options: RequestOptions = {},
  content?: Content,
): Promise<T> {
  const query: Record<string, unknown> = {};
  const body: Record<string, unknown> = {};
  for (const [name, value] of Object.entries(input ?? {})) {
    if (value === undefined) continue;
    (op.query.includes(name) ? query : body)[name] = value;
  }
  const headers = {
    ...options.headers,
    ...(options.idempotencyKey
      ? { "idempotency-key": options.idempotencyKey }
      : {}),
  };
  const request = client.request as unknown as (
    method: Method,
    path: string,
    init: object,
  ) => Promise<{ data?: unknown; error?: unknown; response: Response }>;
  // Raw bytes go as they are, typed by the Blob (else the route's type).
  const raw = op.rawBody
    ? content instanceof Blob
      ? content
      : new Blob([content] as ConstructorParameters<typeof Blob>[0])
    : undefined;
  const { data, error, response } = await request(op.method, op.path, {
    params: { path: pathParams, query },
    ...(op.hasBody ? { body } : {}),
    ...(raw
      ? {
          body: raw,
          bodySerializer: (value: unknown) => value,
          headers: { "content-type": raw.type || op.rawBody, ...headers },
        }
      : { headers }),
    ...(op.rawResponse ? { parseAs: "blob" } : {}),
  });
  if (error !== undefined || !response.ok) {
    throw apiErrorFrom(error, response);
  }
  return data as T;
}
